function parseNpmRef(source) {
  const l = source.slice(4)
  if (!l) throw new Error(`Invalid npm reference: "${source}"`)
  let pkgName, version

  if (l.startsWith('@')) {
    const slashIdx = l.indexOf('/')
    if (slashIdx === -1) throw new Error(`Invalid npm reference: "${source}"`)
    const rest = l.slice(slashIdx + 1)
    const atIdx = rest.indexOf('@')
    if (atIdx > 0) {
      pkgName = l.slice(0, slashIdx + 1 + atIdx)
      version = rest.slice(atIdx + 1)
    } else {
      pkgName = l
      version = 'latest'
    }
  } else {
    const atIdx = l.lastIndexOf('@')
    if (atIdx > 0) {
      pkgName = l.slice(0, atIdx)
      version = l.slice(atIdx + 1)
    } else {
      pkgName = l
      version = 'latest'
    }
  }

  return { pkgName, version }
}
